CREATE OR REPLACE FUNCTION calculate_avg_delay_hours(p_carrier_code VARCHAR(10), p_cutoff_date DATE)
RETURNS NUMERIC AS $$
DECLARE
  avg_delay NUMERIC;
BEGIN
  SELECT ROUND(AVG(EXTRACT(EPOCH FROM (actual_delivery_timestamp - promised_delivery_timestamp)) / 3600.0), 2)
  INTO avg_delay
  FROM shipments
  WHERE carrier_code = p_carrier_code
    AND actual_delivery_timestamp::DATE > p_cutoff_date
    AND actual_delivery_timestamp > promised_delivery_timestamp;

  RETURN COALESCE(avg_delay, 0);
END;
$$ LANGUAGE plpgsql;

SELECT calculate_avg_delay_hours('DHL', '2024-01-15') AS result;
